from collections import Counter
import re
import itertools

class NLPDataProcessor2:
    TOP_N_WORDS = 5

    def __init__(self):
        self._string_list = []

    @property
    def string_list(self):
        return self._string_list

    @string_list.setter
    def string_list(self, value):
        self._string_list = value

    def _clean_string(self, string):
        """Remove non-English letters and convert to lowercase"""
        return re.sub(r'[^a-zA-Z\s]', '', string.lower())

    def _extract_words(self, string):
        """Split the processed string into words"""
        return self._clean_string(string).split()

    def _build_words_list(self):
        """Convert string list into a list of word lists"""
        return [self._extract_words(string) for string in self.string_list]

    def _calculate_word_frequencies(self, words_list):
        """Calculate and sort word frequencies, returning top N"""
        word_frequency = Counter()
        for words in words_list:
            word_frequency.update(words)
        sorted_word_frequency = dict(sorted(word_frequency.items(), key=lambda x: x[1], reverse=True))
        top_n_word_frequency = dict(itertools.islice(sorted_word_frequency.items(), self.TOP_N_WORDS))
        return top_n_word_frequency

    def process(self):
        """Process the stored string list to get top word frequencies"""
        words_list = self._build_words_list()
        word_frequency_dict = self._calculate_word_frequencies(words_list)
        return word_frequency_dict
